# Run with a generated Bytes.schema directory to compare compiler revisions.
[base | _] = System.argv()
Code.require_file("TableRuntime.ex", base)
Code.require_file("BytesTable.ex", base)

for size <- [16, 4096, 16384] do
  values =
    for variant <- 0..63 do
      payload = for i <- 0..(size - 1), into: <<>>, do: <<rem(i * 73 + variant, 256)>>
      text = "{\"payload\":\"" <> Base.encode64(payload) <> "\"}"
      {value, report} = Base64test.BytesTable.from_json_blob(text)
      false = report.malformed
      ^payload = value.payload
      {text, value}
    end

  for operation <- [:read, :write] do
    run = fn ->
      for {text, value} <- values do
        case operation do
          :read -> Base64test.BytesTable.from_json_blob(text)
          :write -> Base64test.BytesTable.to_json_blob(value)
        end
      end
    end

    run.()

    samples =
      for _ <- 1..5 do
        :erlang.garbage_collect()
        {us, _result} = :timer.tc(run)
        us / length(values)
      end

    median = samples |> Enum.sort() |> Enum.at(2)
    IO.puts("#{operation},#{size},#{Float.round(median, 3)}")
  end
end
